window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b9e2234d09aeac9d"]={"versions": [{"id": "FIG-b9e2234d09aeac9d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm (M2-Ebene nach MOF/AUTOSAR Generic Structure Template).\n</li><li><strong>Technischer Zweck:</strong> Etablierung des abstrakten „Definition/Value“-Entwurfsmusters (Type-Instance / Schema-Value-Separation) für die Zielkonfiguration der Adaptive Machine (<em>Machine Configuration</em>).\n</li><li><strong>Architektur-Kontext:</strong> Das Diagramm entkoppelt die formale Parameterdefinition (bereitgestellt durch Tool- oder Plattformhersteller) von den tatsächlichen Konfigurationswerten (konfiguriert durch Systemintegratoren/OEMs für ein konkretes Target) im Kontext von <code>AUTOSAR_AP_TPS_MachineConfiguration</code> (Release R24-11).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Basismetasklasse des AUTOSAR Generic Structure Template (<code>AUTOSAR_TPS_GenericStructureTemplate</code>).\n</li><li>Vererbt Eigenschaften zur eindeutigen Identifikation und Adressierbarkeit im ARXML-Pfadbaum (<code>shortName</code>, <code>category</code>, <code>adminData</code>, <code>uuid</code>).\n</li></ul>\n</li><li><strong><code>ApmcAbstractDefinition</code> (kursiv, abstrakt):</strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>Identifiable</code>.\n</li><li>Wurzelklasse aller Metaklassen, die Schema- oder Metadatenstrukturen für Maschinenkonfigurationsparameter definieren (z. B. Prozessorkerne, Speicherlayouts, OS-Ressourcen).\n</li></ul>\n</li><li><strong><code>ApmcAbstractValue</code> (kursiv, abstrakt):</strong>\n<ul class=\"fig-list\"><li>Wurzelklasse aller Metaklassen, die konkrete Instanzwerte für Parameter einer Machine Configuration kapseln.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Assoziationen:</strong>\n<ul class=\"fig-list\"><li><strong>Assoziation <code>+definition</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Richtung:</strong> Unidirektional von <code>ApmcAbstractValue</code> nach <code>ApmcAbstractDefinition</code>.\n</li><li><strong>Kardinalität:</strong> <code>0..1</code> an der Zielseite (<code>ApmcAbstractDefinition</code>). Ein Konfigurationswert referenziert maximal eine Parameterdefinition; Zwischenzustände ohne aufgelöste Referenz während der Modellierung sind zulässig.\n</li><li><strong>Stereotyp <code>«atpAbstract»</code>:</strong> Markiert die Assoziation auf Metamodellebene als abstrakt. Sie darf auf M1-Ebene nicht direkt instanziiert werden, sondern muss durch konkrete Subklassen mit typspezifischen Referenzen redefiniert und spezialisiert werden.\n</li></ul>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Dynamik:</strong> Nicht zutreffend. Es handelt sich um ein rein statisches Metamodell zur Entwurfszeit (Compile-/Design-Time, M2-Spezifikation).\n</li><li><strong>Toolchain- und Modellierungs-Lebenszyklus:</strong>\n<ol class=\"fig-list\"><li><strong>Definitionsphase:</strong> Bereitstellung von Parametertypen und Strukturdefinitionen über spezialisierte Subklassen von <code>ApmcAbstractDefinition</code>.\n</li><li><strong>Konfigurationsphase:</strong> Belegung der Werte für eine Zielmaschine über spezialisierte Subklassen von <code>ApmcAbstractValue</code> unter Bindung an die jeweilige <code>definition</code>.\n</li><li><strong>Validierung &amp; Generierung:</strong> Modellprüfung auf Schema-Konformität und Konsistenz der <code>+definition</code>-Referenzen vor der Generierung von Machine Manifests / Execution Manifests.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Modellierungsregeln (ARXML / M1):</strong>\n<ul class=\"fig-list\"><li>Beide Metaklassen sind abstrakt; Entwickler und Generatoren instanziieren ausschließlich deren konkrete Subklassen.\n</li><li>Das Stereotyp <code>«atpAbstract»</code> verlangt von Validierungs- und Codegenerierungs-Tools, die abgeleiteten konkreten Assoziationen semantisch auf Übereinstimmung von Wertebereich und Typdefinition zu prüfen.\n</li></ul>\n</li><li><strong>Trennung von Rollen und Artefakten:</strong>\n<ul class=\"fig-list\"><li>Erlaubt die Trennung von Plattform-Lieferumfang (Definitions-Templates) und anwendungsspezifischer Maschinenkonfiguration (Wertebelegung im Integrationsprojekt).\n</li></ul>\n</li><li><strong>Auswirkung auf Toolchain-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Bei inkrementeller Modellerstellung oder getrennten ARXML-Paketen muss der Tool-Parser temporär unaufgelöste <code>definition</code>-Referenzen (Multiplizität <code>0..1</code>) tolerieren, muss diese jedoch vor dem finalen Deployment-Build als Pflichtbindung einfordern.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8d494c4a5b21d5ee", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Ausschnitt als UML-Klassendiagramm (M2-Ebene nach MOF/AUTOSAR Generic Structure Template).\n</li><li><strong>Technischer Zweck:</strong> Etablierung des abstrakten „Definition/Value“-Entwurfsmusters (Type-Instance / Schema-Value-Separation) für die Zielkonfiguration der Adaptive Machine (<em>Machine Configuration</em>).\n</li><li><strong>Architektur-Kontext:</strong> Das Diagramm entkoppelt die formale Parameterdefinition (bereitgestellt durch Tool- oder Plattformhersteller) von den tatsächlichen Konfigurationswerten (konfiguriert durch Systemintegratoren/OEMs für ein konkretes Target) im Kontext von <code>AUTOSAR_AP_TPS_MachineConfiguration</code> (Release R24-11).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrakte Basismetasklasse des AUTOSAR Generic Structure Template (<code>AUTOSAR_TPS_GenericStructureTemplate</code>).\n</li><li>Vererbt Eigenschaften zur eindeutigen Identifikation und Adressierbarkeit im ARXML-Pfadbaum (<code>shortName</code>, <code>category</code>, <code>adminData</code>, <code>uuid</code>).\n</li></ul>\n</li><li><strong><code>ApmcAbstractDefinition</code> (kursiv, abstrakt):</strong>\n<ul class=\"fig-list\"><li>Spezialisiert <code>Identifiable</code>.\n</li><li>Wurzelklasse aller Metaklassen, die Schema- oder Metadatenstrukturen für Maschinenkonfigurationsparameter definieren (z. B. Prozessorkerne, Speicherlayouts, OS-Ressourcen).\n</li></ul>\n</li><li><strong><code>ApmcAbstractValue</code> (kursiv, abstrakt):</strong>\n<ul class=\"fig-list\"><li>Wurzelklasse aller Metaklassen, die konkrete Instanzwerte für Parameter einer Machine Configuration kapseln.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Assoziationen:</strong>\n<ul class=\"fig-list\"><li><strong>Assoziation <code>+definition</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Richtung:</strong> Unidirektional von <code>ApmcAbstractValue</code> nach <code>ApmcAbstractDefinition</code>.\n</li><li><strong>Kardinalität:</strong> <code>0..1</code> an der Zielseite (<code>ApmcAbstractDefinition</code>). Ein Konfigurationswert referenziert maximal eine Parameterdefinition; Zwischenzustände ohne aufgelöste Referenz während der Modellierung sind zulässig.\n</li><li><strong>Stereotyp <code>«atpAbstract»</code>:</strong> Markiert die Assoziation auf Metamodellebene als abstrakt. Sie darf auf M1-Ebene nicht direkt instanziiert werden, sondern muss durch konkrete Subklassen mit typspezifischen Referenzen redefiniert und spezialisiert werden.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Dynamik:</strong> Nicht zutreffend. Es handelt sich um ein rein statisches Metamodell zur Entwurfszeit (Compile-/Design-Time, M2-Spezifikation).\n</li><li><strong>Toolchain- und Modellierungs-Lebenszyklus:</strong>\n<ol class=\"fig-list\"><li><strong>Definitionsphase:</strong> Bereitstellung von Parametertypen und Strukturdefinitionen über spezialisierte Subklassen von <code>ApmcAbstractDefinition</code>.\n</li><li><strong>Konfigurationsphase:</strong> Belegung der Werte für eine Zielmaschine über spezialisierte Subklassen von <code>ApmcAbstractValue</code> unter Bindung an die jeweilige <code>definition</code>.\n</li><li><strong>Validierung &amp; Generierung:</strong> Modellprüfung auf Schema-Konformität und Konsistenz der <code>+definition</code>-Referenzen vor der Generierung von Machine Manifests / Execution Manifests.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Modellierungsregeln (ARXML / M1):</strong>\n<ul class=\"fig-list\"><li>Beide Metaklassen sind abstrakt; Entwickler und Generatoren instanziieren ausschließlich deren konkrete Subklassen.\n</li><li>Das Stereotyp <code>«atpAbstract»</code> verlangt von Validierungs- und Codegenerierungs-Tools, die abgeleiteten konkreten Assoziationen semantisch auf Übereinstimmung von Wertebereich und Typdefinition zu prüfen.\n</li></ul>\n</li><li><strong>Trennung von Rollen und Artefakten:</strong>\n<ul class=\"fig-list\"><li>Erlaubt die Trennung von Plattform-Lieferumfang (Definitions-Templates) und anwendungsspezifischer Maschinenkonfiguration (Wertebelegung im Integrationsprojekt).\n</li></ul>\n</li><li><strong>Auswirkung auf Toolchain-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Bei inkrementeller Modellerstellung oder getrennten ARXML-Paketen muss der Tool-Parser temporär unaufgelöste <code>definition</code>-Referenzen (Multiplizität <code>0..1</code>) tolerieren, muss diese jedoch vor dem finalen Deployment-Build als Pflichtbindung einfordern.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b9e2234d09aeac9d", "to": "FIG-8d494c4a5b21d5ee", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
